def set_category_rewards(apps, schema_editor):
    """Completing a whole category pays 2.00 into the wallet, 1.00 in Nigeria."""
    Config = apps.get_model('surveys', 'CountryLuckyDrawConfig')
    for config in Config.objects.select_related('country'):
        code = str(config.country.code).upper() if config.country_id else ''
        config.category_completion_reward = Decimal('1.00') if code == 'NG' else Decimal('2.00')
        config.save(update_fields=['category_completion_reward'])


